export const VARIABLES = ROWS.map(([id, area, block, section, name, sysvar, description]) => ({
    id, area, block, section, name, sysvar, description,
}));

/** Case-insensitive search over name + sysvar + description, optional area/block
 *  filter. Returns at most 200 matches (UI cap); [] for no match. */
export function searchVars({ query, area, block } = {}) {
    const q = String(query || '').trim().toLowerCase();
    if (q === '' && !area && !block) return [];
    const out = [];
    for (const v of VARIABLES) {
        if (area && v.area !== area) continue;
        if (block && v.block !== block) continue;
        if (q) {
            const hay = (v.name + ' ' + (v.sysvar || '') + ' ' + v.description).toLowerCase();
            if (!hay.includes(q)) continue;
        }
        out.push(v);
        if (out.length >= 200) break;
    }
    return out;
}
